#!/usr/bin/env bun
// Copies the Autodoc bundle generated by `zig build docs` into public/api, so
// the Astro build (and `astro dev`) serves the API reference at /pgzx/api/.
//
// public/api is generated output and git-ignored; run this once before a local
// `bun run dev`, and it runs automatically before `bun run build`.

import { cp, mkdir, rm } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const docsDir = new URL('..', import.meta.url).pathname;
const repoRoot = resolve(docsDir, '..');
const source = join(repoRoot, 'zig-out', 'share', 'pgzx', 'docs');
const dest = join(docsDir, 'public', 'api');

const zig = Bun.spawnSync({
  cmd: ['zig', 'build', 'docs'],
  cwd: repoRoot,
  stdin: 'inherit',
  stdout: 'inherit',
  stderr: 'inherit',
});

if (zig.exitCode !== 0) {
  console.error('error: `zig build docs` failed; the API reference was not updated');
  process.exit(zig.exitCode ?? 1);
}

// Start from a clean directory: `cp -r` into an existing tree would otherwise
// leave stale hashed files behind, and `cp src dest` where dest exists nests
// src inside it.
await rm(dest, { recursive: true, force: true });
await mkdir(dest, { recursive: true });
await cp(source, dest, { recursive: true });

console.log(`synced ${source} -> ${dest}`);
